#!/bin/bash
# Idempotent WooCommerce setup for a provisioned store; run by the `store-setup-<n>` Job.
#
# Runs as many times as needed: every step either checks first or sets an absolute value, and the
# REST key is replaced, not added. WP-CLI uses its own wp-config.php generated from the database
# environment, so the Job does not need the WordPress volume.
#
# Environment: DB_HOST, DB_PORT, DB_NAME, DB_USER, DB_PASSWORD, WP_ADMIN_USER,
#   WC_CONSUMER_KEY, WC_CONSUMER_SECRET (generated by the provisioner), STORE_NAME,
#   STORE_COUNTRY (default US:CA), STORE_CURRENCY (default USD), SEED_DEMO (true|false),
#   WAIT_SECONDS (default 600: how long to wait for WordPress to finish its first install).
set -euo pipefail

: "${DB_HOST:?}" "${DB_NAME:?}" "${DB_USER:?}" "${DB_PASSWORD:?}"
: "${WC_CONSUMER_KEY:?}" "${WC_CONSUMER_SECRET:?}" "${WP_ADMIN_USER:?}"
export HOME=/tmp WP_CLI_CACHE_DIR=/tmp/wp-cli-cache
WP_PATH=/opt/bitnami/wordpress
wp() { /opt/bitnami/wp-cli/bin/wp --path="${WP_PATH}" --quiet "$@"; }
log() { echo "store-setup: $*"; }

wp config create --force --skip-check --skip-salts \
  --dbname="${DB_NAME}" --dbuser="${DB_USER}" --dbpass="${DB_PASSWORD}" \
  --dbhost="${DB_HOST}:${DB_PORT:-3306}" --dbprefix=wp_

# WordPress installs itself on its first boot; wait for that instead of racing it.
deadline=$((SECONDS + ${WAIT_SECONDS:-600}))
until wp core is-installed 2>/dev/null; do
  if ((SECONDS >= deadline)); then
    log "WordPress did not finish installing within ${WAIT_SECONDS:-600}s"
    exit 1
  fi
  log "waiting for WordPress to be installed"
  sleep 5
done

if ! wp plugin is-active woocommerce; then
  log "activating WooCommerce"
  wp plugin activate woocommerce
fi

log "configuring the store"
wp rewrite structure '/%postname%/'
# update_option() returns false when the value is unchanged, so its result is not checked; a
# final read-back verifies the values instead.
wp eval '
$options = [
  "blogname" => getenv("STORE_NAME") ?: "Urumi Store",
  "woocommerce_default_country" => getenv("STORE_COUNTRY") ?: "US:CA",
  "woocommerce_currency" => getenv("STORE_CURRENCY") ?: "USD",
  // No onboarding wizard and no "coming soon" page: the storefront is usable at once.
  "woocommerce_onboarding_profile" => ["skipped" => true],
  "woocommerce_task_list_hidden" => "yes",
  "woocommerce_coming_soon" => "no",
  "woocommerce_store_pages_only" => "no",
  "woocommerce_cod_settings" => [
    "enabled" => "yes",
    "title" => "Cash on delivery",
    "description" => "Pay with cash upon delivery.",
    "instructions" => "Pay with cash upon delivery.",
    "enable_for_methods" => [],
    "enable_for_virtual" => "yes",
  ],
];
foreach ($options as $name => $value) {
  update_option($name, $value);
  if (get_option($name) != $value) { WP_CLI::error("option $name was not saved"); }
}
'

log "installing the REST API key"
wp eval '
global $wpdb;
$user = get_user_by("login", getenv("WP_ADMIN_USER"));
if (!$user) {
  $admins = get_users(["role" => "administrator", "number" => 1]);
  $user = $admins ? $admins[0] : null;
}
if (!$user) { WP_CLI::error("no administrator account"); }
$ck = getenv("WC_CONSUMER_KEY");
$table = $wpdb->prefix . "woocommerce_api_keys";
$wpdb->delete($table, ["description" => "urumi store-mcp"]);
$ok = $wpdb->insert($table, [
  "user_id" => $user->ID,
  "description" => "urumi store-mcp",
  "permissions" => "read_write",
  "consumer_key" => wc_api_hash($ck),
  "consumer_secret" => getenv("WC_CONSUMER_SECRET"),
  "truncated_key" => substr($ck, -7),
]);
if (!$ok) { WP_CLI::error("could not store the API key"); }
'

if [[ "${SEED_DEMO:-false}" == "true" ]]; then
  wp eval '
$existing = wc_get_products(["limit" => 1, "return" => "ids", "status" => "any"]);
if ($existing) { return; }
foreach ([["Classic Mug", "12.00"], ["Canvas Tote", "18.50"], ["Sticker Pack", "4.99"]] as [$name, $price]) {
  $p = new WC_Product_Simple();
  $p->set_name($name);
  $p->set_regular_price($price);
  $p->set_status("publish");
  $p->save();
}
'
  log "demo products ready"
fi

wp cache flush || true
log "done"
